{"foils":[{"nl":"For a 10x10 grid, fill the top five rows with 2 and the bottom five rows with 0.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    return [[2 if r < h//2 else 0 for _ in range(w)] for r in range(h)]"},{"nl":"Fill every cell in the upper half with the most frequent nonzero color, defaulting to 2, and clear the lower half.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    vals=[x for row in grid for x in row if x]
    color=2 if not vals else max(set(vals), key=vals.count)
    return [[color if r<h//2 else 0 for _ in range(w)] for r in range(h)]"},{"nl":"If the grid is 10x10 with exactly two nonzero cells colored 2 and 6, output a solid 2 rectangle in the top half; otherwise leave it unchanged.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    nz=[x for row in grid for x in row if x]
    if h==10 and w==10 and sorted(nz)==[2,6]:
        return [[2 if r<5 else 0 for _ in range(w)] for r in range(h)]
    return [row[:] for row in grid]"},{"nl":"Replace each row by ten 2s for the first half of rows and ten 0s for the second half, ignoring the input.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    return [[2]*w if r<5 else [0]*w for r in range(h)]"},{"nl":"Project the color 2 upward: make all cells above the horizontal midpoint 2 and erase all cells at or below it.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    mid=h//2
    return [[2 if r<mid else 0 for c in range(w)] for r in range(h)]"},{"nl":"For the demonstrated shape, draw a 5-by-10 block of color 2 at the top; for any other shape, draw a 2 block whose height equals the number of nonzero cells.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    nz=sum(x!=0 for row in grid for x in row)
    if h==10 and w==10 and nz==2 and sorted(x for row in grid for x in row if x)==[2,6]: k=5
    else: k=min(h,nz)
    return [[2 if r<k else 0 for _ in range(w)] for r in range(h)]"},{"nl":"Turn the grid into a horizontal two-color partition: the upper half is 2 and the lower half is 0.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    return [[2 if r < (h+1)//2 else 0 for c in range(w)] for r in range(h)]"},{"nl":"For a 10x10 input containing one 2 and one 6, output 2 wherever the row index is less than 5 and zero elsewhere; otherwise preserve the input.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    nz=[x for row in grid for x in row if x]
    if (h,w)==(10,10) and nz.count(2)==1 and nz.count(6)==1 and len(nz)==2:
        return [[2 if r<5 else 0 for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]"},{"nl":"Ignore positions and encode the presence of two nonzero objects as five rows of 2 followed by five rows of 0.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    n=sum(x!=0 for row in grid for x in row)
    k=5 if n==2 and (h,w)==(10,10) else 0
    return [[2 if r<k else 0 for c in range(w)] for r in range(h)]"},{"nl":"Paint the upper half with color 2 and erase the lower half, but use a one-row upper band for non-10x10 grids.","code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    k=5 if (h,w)==(10,10) else min(1,h)
    return [[2 if r<k else 0 for c in range(w)] for r in range(h)]"}]}

